func TestConvertFortinetToModel(t *testing.T) {
	published := time.Date(2023, 1, 2, 0, 0, 0, 0, time.UTC)
	modified := published.Add(time.Hour)
	got := ConvertFortinetToModel("CVE-2023-1234", []cvedict.Fortinet{{
		AdvisoryID: "FG-IR-23-001", Title: "FortiOS issue", Summary: "Affected versions",
		AdvisoryURL: "https://www.fortiguard.com/psirt/FG-IR-23-001",
		Cvss3: cvedict.FortinetCvss3{Cvss3: cvedict.Cvss3{
			BaseScore: 8.1, VectorString: "CVSS:3.1/AV:N", BaseSeverity: "HIGH",
		}},
		Cwes: []cvedict.FortinetCwe{{CweID: "CWE-79"}},
		References: []cvedict.FortinetReference{{Reference: cvedict.Reference{
			Link: "https://example.com/reference", Source: "Fortinet",
		}}},
		PublishedDate: published, LastModifiedDate: modified,
	}})
	want := []CveContent{{
		Type: Fortinet, CveID: "CVE-2023-1234", Title: "FortiOS issue", Summary: "Affected versions",
		Cvss3Score: 8.1, Cvss3Vector: "CVSS:3.1/AV:N", Cvss3Severity: "HIGH",
		SourceLink: "https://www.fortiguard.com/psirt/FG-IR-23-001",
		CweIDs:     []string{"CWE-79"}, References: []Reference{{Link: "https://example.com/reference", Source: "Fortinet"}},
		Published: published, LastModified: modified,
	}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("ConvertFortinetToModel() = %#v, want %#v", got, want)
	}
}

}

// FillCvesWithNvdJvnFortinet fills CVE detail with NVD, JVN, and Fortinet.
func FillCvesWithNvdJvnFortinet(r *models.ScanResult, cnf config.GoCveDictConf, logOpts logging.LogOpts) (err error) {
	cveIDs := []string{}
	for _, v := range r.ScannedCves {
		cveIDs = append(cveIDs, v.CveID)
	}

	client, err := newGoCveDictClient(&cnf, logOpts)
	if err != nil {
		return xerrors.Errorf("Failed to newGoCveDictClient. err: %w", err)
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	ds, err := client.fetchCveDetails(cveIDs)
	if err != nil {
		return xerrors.Errorf("Failed to fetchCveDetails. err: %w", err)
	}

	for _, d := range ds {
		nvds, exploits, mitigations := models.ConvertNvdToModel(d.CveID, d.Nvds)
		jvns := models.ConvertJvnToModel(d.CveID, d.Jvns)
		fortinets := models.ConvertFortinetToModel(d.CveID, d.Fortinets)

		alerts := fillCertAlerts(&d)
		for cveID, vinfo := range r.ScannedCves {
			if vinfo.CveID == d.CveID {
				if vinfo.CveContents == nil {
					vinfo.CveContents = models.CveContents{}
				}
				for _, con := range nvds {
					if !con.Empty() {
						vinfo.CveContents[con.Type] = []models.CveContent{con}
					}
				}
				for _, con := range jvns {
					if !con.Empty() {
						found := false
						for _, cveCont := range vinfo.CveContents[con.Type] {
							if con.SourceLink == cveCont.SourceLink {
								found = true
								break
							}
						}
						if !found {
							vinfo.CveContents[con.Type] = append(vinfo.CveContents[con.Type], con)
						}
					}
				}
				for _, con := range fortinets {
					found := false
					for _, existing := range vinfo.CveContents[con.Type] {
						if con.SourceLink == existing.SourceLink {
							found = true
							break
						}
					}
					if !found {
						vinfo.CveContents[con.Type] = append(vinfo.CveContents[con.Type], con)
					}
				}
				vinfo.AlertDict = alerts
				vinfo.Exploits = append(vinfo.Exploits, exploits...)
				vinfo.Mitigations = append(vinfo.Mitigations, mitigations...)
				r.ScannedCves[cveID] = vinfo
				break
			}
		}

		logging.Log.Infof("%s: %d unfixed CVEs are detected with gost", r.FormatServerName(), nCVEs)
	}

	return nil
}

// DetectCpeURIsCves detects CVEs of given CPE-URIs
func DetectCpeURIsCves(r *models.ScanResult, cpes []Cpe, cnf config.GoCveDictConf, logOpts logging.LogOpts) error {
	client, err := newGoCveDictClient(&cnf, logOpts)
	if err != nil {
		return xerrors.Errorf("Failed to newGoCveDictClient. err: %w", err)
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	nCVEs := 0
	for _, cpe := range cpes {
		details, err := client.detectCveByCpeURI(cpe.CpeURI, cpe.UseJVN)
		if err != nil {
			return xerrors.Errorf("Failed to detectCveByCpeURI. err: %w", err)
		}

		for _, detail := range details {
			advisories := []models.DistroAdvisory{}
			if !detail.HasNvd() && detail.HasJvn() {
				for _, jvn := range detail.Jvns {
					advisories = append(advisories, models.DistroAdvisory{
						AdvisoryID: jvn.JvnID,
					})
				}
			}
			for _, fortinet := range detail.Fortinets {
				advisories = append(advisories, models.DistroAdvisory{AdvisoryID: fortinet.AdvisoryID})
			}
			maxConfidence := getMaxConfidence(detail)

			if val, ok := r.ScannedCves[detail.CveID]; ok {
				val.CpeURIs = util.AppendIfMissing(val.CpeURIs, cpe.CpeURI)
				val.Confidences.AppendIfMissing(maxConfidence)
				for _, advisory := range advisories {
					found := false
					for _, existing := range val.DistroAdvisories {
						if existing.AdvisoryID == advisory.AdvisoryID {
							found = true
							break
						}
					}
					if !found {
						val.DistroAdvisories = append(val.DistroAdvisories, advisory)
					}
				}
				r.ScannedCves[detail.CveID] = val
			} else {
				v := models.VulnInfo{
					CveID:            detail.CveID,
					CpeURIs:          []string{cpe.CpeURI},
					Confidences:      models.Confidences{maxConfidence},
					DistroAdvisories: advisories,
				}
				r.ScannedCves[detail.CveID] = v
				nCVEs++
			}
		}
	}
	logging.Log.Infof("%s: %d CVEs are detected with CPE", r.FormatServerName(), nCVEs)
	return nil
}

